mapper.select:
SELECT * FROM sys_user
is_deleted = 0 AND username LIKE CONCAT('%', #{username}, '%') AND real_name LIKE CONCAT('%', #{realName}, '%') AND status = #{status}
ORDER BY created_at DESC

mapper.update:
UPDATE sys_user
password = #{password}, real_name = #{realName}, phone = #{phone}, email = #{email}, status = #{status}, updated_by = #{updatedBy}, updated_at = NOW()
WHERE id = #{id}
